public int maxTurbulenceSize(int n, int[][] edges, int[] restricted) {
    // Create a graph to represent the connections between nodes
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
