    // Remove restricted nodes from the graph
    for (int node : restricted) {
        graph.get(node).clear();
    }

    // Find the maximum turbulence size
    int result = 0;
    for (int i = 0; i < n; i++) {
        if (graph.get(i).size() > 0) {
            int size = dfs(graph, i, -1);
            result = Math.max(result, size);
        }
    }

