private int dfs(List<List<Integer>> graph, int node, int parent) {
    int size = 1;
    for (int neighbor : graph.get(node)) {
        if (neighbor != parent) {
            size = Math.max(size, 1 + dfs(graph, neighbor, node));
        }
    }
    return size;
}

