    int n = grid.size();
    std::vector<int> row_zeros(n, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j] == 0) {
                row_zeros[i]++;
            } else {
                break;
            }
        }
    }

    int steps = 0;
    for (int i = 0; i < n; ++i) {
        int target = n - i - 1;
