bool canPartition(vector<int>& arr) {
    int n = arr.size();
    int sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += arr[i];
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    vector<vector<bool>> dp(n + 1, vector<bool>(target + 1, false));
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = true;
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= target; ++j) {
            if (j < arr[i - 1]) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - arr[i - 1]];
            }
        }
    }
    return dp[n][target];
}

