public class Solution {
    public boolean[] canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        int[][] prefix = new int[n + 1][26];
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < 26; j++) {
                prefix[i][j] = prefix[i - 1][j];
            }
            prefix[i][s.charAt(i - 1) - 'a']++;
        }
        boolean[] result = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int k = queries[i][2];
            int[] count = new int[26];
            for (int j = 0; j < 26; j++) {
                count[j] = prefix[r + 1][j] - prefix[l][j];
            }
            int oddCount = 0;
            for (int j = 0; j < 26; j++) {
                if (count[j] % 2 == 1) {
                    oddCount++;
                }
            }
            result[i] = oddCount / 2 <= k;
        }
        return result;
    }
}

