import java.util.*;

public int maxInvites(int[] favorite) {
    int n = favorite.length;
    int[] dp = new int[n];
    int maxInvites = 0;

    for (int i = 0; i < n; i++) {
        dp[i] = (i == favorite[favorite[i]]) ? 2 : 1;
        maxInvites = Math.max(maxInvites, dp[i]);
    }

    return maxInvites;
}

public int maxCoins(int[] coins, int[][] edges) {
    int n = coins.length;
    int[] dp = new int[n];
    int maxCoins = 0;

    for (int i = 0; i < n; i++) {
        dp[i] = (coins[i] == 1) ? 1 : 0;
        for (int[] edge : edges) {
            if (edge[0] == i) {
                dp[i] += dp[edge[1]];
            } else if (edge[1] == i) {
                dp[i] += dp[edge[0]];
            }
        }
        maxCoins = Math.max(maxCoins, dp[i]);
    }

    return maxCoins;
}
